

# This file was *autogenerated* from the file sagemath/check/051_stepwise_identities_of_chapter_Cprime/check_03_014_steps.sage
from sage.all_cmdline import *   # import sage library

_sage_const_8 = Integer(8); _sage_const_40 = Integer(40); _sage_const_1 = Integer(1); _sage_const_0 = Integer(0); _sage_const_2 = Integer(2); _sage_const_0p3 = RealNumber('0.3'); _sage_const_0p7 = RealNumber('0.7'); _sage_const_1p1 = RealNumber('1.1'); _sage_const_0p2 = RealNumber('0.2'); _sage_const_60 = Integer(60)# =========================================================================
# check_03: 014 章（structured-latex/content/014_even_sector_T_action.ts）の
#           **各段の等式そのもの**を、ラベル単位で検証する。
#
#  対象ラベル:
#    def_H1_plus / def_V1_plus_square_root / V1_plus_square_root_property
#    def_V_plus / V1_plus_half_invertible / V2_invertible
#    V_plus_factors_invertible / def_T_V_plus
#    T_V_plus_is_conjugation
#    nesting_of_commutator_of_H_and_check_Z
#    cosh_sinh_coefficient_conversion_for_check
#    extract_taylor_coefficient_of_check_Z_Y
#    T_actions_on_check_Z_Y
#    linearity_of_T_on_check_Z_Y / linearity_of_T_V2
#    calc_of_TxT_check_Z_Y
