#    T_V_plus_check_Z_Y
# =========================================================================
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '_prelude.sage'))

print("=== check_03: 014 章の各段の等式 ===")

S = Steps()
NMAX = _sage_const_8          # n 重交換子の検証範囲
NTAYLOR = _sage_const_40      # 級数の打ち切り次数

for M in STEP_M:
    O = SpinOps(M)
    Id = identity_matrix(CDF, O.d)
    H2 = O.H2
    H1p = O.H1(+_sage_const_1 )

    for p in STEP_PARAMS:
        P = coeffs(p['K1'], p['K2'])
        K1, K2, K2s = P['K1'], P['K2'], P['K2s']

        # -----------------------------------------------------------------
        # 偶セクター生成子から V^{(+)} と共役写像までの各段
        # -----------------------------------------------------------------
        Vh, Vhi = V1p_half(O, K1)
        V2, V2i = V2_mat(O, K2)
        Vp, Vpi = V_plus(O, K1, K2)
        V1p = matrix(CDF, (CDF(I) * RDF(K1) * H1p).exp())
        S.add("V1_plus_square_root_property (1) exp(X)exp(X) = exp(2X)  [theorem_exp_product]",
              Vh * Vh, matrix(CDF, (CDF(I) * RDF(K1) * H1p).exp()))
        S.add("V1_plus_square_root_property (2) = V_1^{(+)}  [def_V1_pm]", Vh * Vh, V1p)
        S.add("V1_plus_half_invertible exp(X)^{-1} = exp(-X)", Vh * Vhi, Id)
        S.add("V2_invertible V_2 V_2^{-1} = I", V2 * V2i, Id)
        S.add("V_plus_factors_invertible (Vplus) V^{(+)} V^{(+)-1} = I", Vp * Vpi, Id)
        # T_V_plus_is_conjugation: T_g(T_h(X)) = T_{gh}(X) の各段
        Xt = checkZ(O, _sage_const_1 )
        S.add("T_V_plus_is_conjugation (1) T_g(T_h(X)) = g(hXh^{-1})g^{-1}",
              Vh * (V2 * Xt * V2i) * Vhi, Vh * (V2 * Xt * V2i) * Vhi)
        S.add("T_V_plus_is_conjugation (2) = (gh)X(h^{-1}g^{-1})  [結合律]",
              Vh * (V2 * Xt * V2i) * Vhi, (Vh * V2) * Xt * (V2i * Vhi))
        # (gh)^{-1} = h^{-1}g^{-1} は「h^{-1}g^{-1} が gh の逆元である」ことの主張なので、
        # 数値的に不安定な inverse() ではなく積が I になることで確かめる
        # （V_2 の前因子 (2s_2)^{M/2} と exp(K_1 ...) のせいで inverse() の条件数が悪い）。
        S.add("T_V_plus_is_conjugation (3) (gh)(h^{-1}g^{-1}) = I",
              (Vh * V2) * (V2i * Vhi), Id)
        S.add("T_V_plus_is_conjugation (4) (h^{-1}g^{-1})(gh) = I",
              (V2i * Vhi) * (Vh * V2), Id)
        S.add("T_V_plus_is_conjugation (5) T_{(V^{(+)})} = T_{V^{(+)}}",
              Vh * (V2 * (Vh * Xt * Vhi) * V2i) * Vhi, Vp * Xt * Vpi)

        for mu in list(range(_sage_const_1 , M + _sage_const_1 )) + [_sage_const_0 , -_sage_const_1 ]:
            t = th_tilde(M, mu)
            Zc, Yc = checkZ(O, mu), checkY(O, mu)

            # -------------------------------------------------------------
            # nesting_of_commutator_of_H_and_check_Z (h1.z)(h1.y)(h2.z)(h2.y)
            # -------------------------------------------------------------
            for n in range(_sage_const_0 , NMAX + _sage_const_1 ):
                sgn_odd = CDF((-_sage_const_1 ) ** ((n - _sage_const_1 ) // _sage_const_2 )) if n % _sage_const_2  == _sage_const_1  else None
                if n % _sage_const_2  == _sage_const_1 :
                    S.add("nesting (h1.z) n 奇数",
                          adpow(RDF(K1) * H1p, Zc, n),
                          CDF((-_sage_const_1 ) ** ((n - _sage_const_1 ) // _sage_const_2 )) * CDF((_sage_const_2  * K1) ** n) * eiph(-t) * Yc)
                    S.add("nesting (h1.y) n 奇数",
                          adpow(RDF(K1) * H1p, Yc, n),
                          CDF((-_sage_const_1 ) ** ((n + _sage_const_1 ) // _sage_const_2 )) * CDF((_sage_const_2  * K1) ** n) * eiph(t) * Zc)
                    S.add("nesting (h2.z) n 奇数",
                          adpow(RDF(K2s) * H2, Zc, n),
                          CDF((-_sage_const_1 ) ** ((n + _sage_const_1 ) // _sage_const_2 )) * CDF((_sage_const_2  * K2s) ** n) * Yc)
                    S.add("nesting (h2.y) n 奇数",
                          adpow(RDF(K2s) * H2, Yc, n),
                          CDF((-_sage_const_1 ) ** ((n - _sage_const_1 ) // _sage_const_2 )) * CDF((_sage_const_2  * K2s) ** n) * Zc)
                else:
                    S.add("nesting (h1.z) n 偶数",
                          adpow(RDF(K1) * H1p, Zc, n),
                          CDF((-_sage_const_1 ) ** (n // _sage_const_2 )) * CDF((_sage_const_2  * K1) ** n) * Zc)
                    S.add("nesting (h1.y) n 偶数",
                          adpow(RDF(K1) * H1p, Yc, n),
                          CDF((-_sage_const_1 ) ** (n // _sage_const_2 )) * CDF((_sage_const_2  * K1) ** n) * Yc)
                    S.add("nesting (h2.z) n 偶数",
                          adpow(RDF(K2s) * H2, Zc, n),
                          CDF((-_sage_const_1 ) ** (n // _sage_const_2 )) * CDF((_sage_const_2  * K2s) ** n) * Zc)
                    S.add("nesting (h2.y) n 偶数",
                          adpow(RDF(K2s) * H2, Yc, n),
                          CDF((-_sage_const_1 ) ** (n // _sage_const_2 )) * CDF((_sage_const_2  * K2s) ** n) * Yc)

                # ---------------------------------------------------------
                # cosh_sinh_coefficient_conversion_for_check の各段
                #   補題 1（生成子のスカラー倍）と補題 2（i^n）を分けて確かめる
                # ---------------------------------------------------------
                alpha_h = CDF(I) / _sage_const_2 
                S.add("係数変換 補題 1 (alpha = i/2, X = K_1 H_1^{(+)}, W = checkZ)",
                      adpow(alpha_h * RDF(K1) * H1p, Zc, n),
                      CDF(alpha_h ** n) * adpow(RDF(K1) * H1p, Zc, n))
                S.add("係数変換 補題 1 (alpha = i/2, W = checkY)",
                      adpow(alpha_h * RDF(K1) * H1p, Yc, n),
                      CDF(alpha_h ** n) * adpow(RDF(K1) * H1p, Yc, n))
                S.add("係数変換 補題 1 (alpha = i, X = K_2^* H_2, W = checkZ)",
                      adpow(CDF(I) * RDF(K2s) * H2, Zc, n),
                      CDF(CDF(I) ** n) * adpow(RDF(K2s) * H2, Zc, n))
                S.add("係数変換 補題 1 (alpha = i, W = checkY)",
                      adpow(CDF(I) * RDF(K2s) * H2, Yc, n),
                      CDF(CDF(I) ** n) * adpow(RDF(K2s) * H2, Yc, n))
                if n % _sage_const_2  == _sage_const_1 :
                    S.add("係数変換 補題 2 (n 奇数) i^n = i(-1)^{(n-1)/2}",
                          CDF(CDF(I) ** n), CDF(I) * CDF((-_sage_const_1 ) ** ((n - _sage_const_1 ) // _sage_const_2 )))
                    S.add("係数変換 (i/2)^n (2K_1)^n = i^n K_1^n",
                          CDF(alpha_h ** n) * CDF((_sage_const_2  * K1) ** n),
                          CDF(CDF(I) ** n) * CDF(K1 ** n))
                    S.add("係数変換 (h1.z) 最終形 (n 奇数)",
                          adpow(alpha_h * RDF(K1) * H1p, Zc, n),
                          CDF(I) * CDF(K1 ** n) * eiph(-t) * Yc)
                    S.add("係数変換 (h1.y) 最終形 (n 奇数)",
                          adpow(alpha_h * RDF(K1) * H1p, Yc, n),
                          -CDF(I) * CDF(K1 ** n) * eiph(t) * Zc)
                    S.add("係数変換 (h2.z) 最終形 (n 奇数)",
                          adpow(CDF(I) * RDF(K2s) * H2, Zc, n),
                          -CDF(I) * CDF((_sage_const_2  * K2s) ** n) * Yc)
                    S.add("係数変換 (h2.y) 最終形 (n 奇数)",
                          adpow(CDF(I) * RDF(K2s) * H2, Yc, n),
                          CDF(I) * CDF((_sage_const_2  * K2s) ** n) * Zc)
                else:
                    S.add("係数変換 補題 2 (n 偶数) i^n = (-1)^{n/2}",
                          CDF(CDF(I) ** n), CDF((-_sage_const_1 ) ** (n // _sage_const_2 )))
                    S.add("係数変換 (h1.z) 最終形 (n 偶数)",
                          adpow(alpha_h * RDF(K1) * H1p, Zc, n), CDF(K1 ** n) * Zc)
                    S.add("係数変換 (h1.y) 最終形 (n 偶数)",
                          adpow(alpha_h * RDF(K1) * H1p, Yc, n), CDF(K1 ** n) * Yc)
                    S.add("係数変換 (h2.z) 最終形 (n 偶数)",
                          adpow(CDF(I) * RDF(K2s) * H2, Zc, n), CDF((_sage_const_2  * K2s) ** n) * Zc)
                    S.add("係数変換 (h2.y) 最終形 (n 偶数)",
                          adpow(CDF(I) * RDF(K2s) * H2, Yc, n), CDF((_sage_const_2  * K2s) ** n) * Yc)

            # -------------------------------------------------------------
            # extract_taylor_coefficient_of_check_Z_Y の各段
            #   偶数項・奇数項に分けて cosh/sinh へ集約する段を別々に確かめる
            # -------------------------------------------------------------
            def part_sum(gen, W):
                out = matrix(CDF, O.d, O.d, _sage_const_0 )
                f = RDF(_sage_const_1 )
                for n in range(_sage_const_0 , NTAYLOR + _sage_const_1 ):
                    if n > _sage_const_0 :
                        f = f / n
                    out = out + f * adpow(gen, W, n)
                return matrix(CDF, out)

            even_h1 = sum([CDF(K1 ** n) / factorial(n) for n in range(_sage_const_0 , NTAYLOR + _sage_const_1 , _sage_const_2 )], CDF(_sage_const_0 ))
            odd_h1 = sum([CDF(K1 ** n) / factorial(n) for n in range(_sage_const_1 , NTAYLOR + _sage_const_1 , _sage_const_2 )], CDF(_sage_const_0 ))
            even_h2 = sum([CDF((_sage_const_2  * K2s) ** n) / factorial(n) for n in range(_sage_const_0 , NTAYLOR + _sage_const_1 , _sage_const_2 )], CDF(_sage_const_0 ))
            odd_h2 = sum([CDF((_sage_const_2  * K2s) ** n) / factorial(n) for n in range(_sage_const_1 , NTAYLOR + _sage_const_1 , _sage_const_2 )], CDF(_sage_const_0 ))
            S.add("テイラー抽出 偶数側の和 = cosh K_1", even_h1, CDF(cosh(K1)))
            S.add("テイラー抽出 奇数側の和 = sinh K_1", odd_h1, CDF(sinh(K1)))
            S.add("テイラー抽出 偶数側の和 = cosh 2K_2*", even_h2, CDF(cosh(_sage_const_2  * K2s)))
            S.add("テイラー抽出 奇数側の和 = sinh 2K_2*", odd_h2, CDF(sinh(_sage_const_2  * K2s)))
            S.add("テイラー抽出 (h1.z) 偶奇に分けた形",
                  part_sum(CDF(I) / _sage_const_2  * RDF(K1) * H1p, Zc),
                  even_h1 * Zc + CDF(I) * eiph(-t) * odd_h1 * Yc)
            S.add("テイラー抽出 (h1.z) = cosh Z + i e^{-it} sinh Y",
                  part_sum(CDF(I) / _sage_const_2  * RDF(K1) * H1p, Zc),
                  CDF(cosh(K1)) * Zc + CDF(I) * eiph(-t) * CDF(sinh(K1)) * Yc)
            S.add("テイラー抽出 (h1.y) = -i e^{it} sinh Z + cosh Y",
                  part_sum(CDF(I) / _sage_const_2  * RDF(K1) * H1p, Yc),
                  -CDF(I) * eiph(t) * CDF(sinh(K1)) * Zc + CDF(cosh(K1)) * Yc)
            S.add("テイラー抽出 (h2.z) = cosh Z - i sinh Y",
                  part_sum(CDF(I) * RDF(K2s) * H2, Zc),
                  CDF(cosh(_sage_const_2  * K2s)) * Zc - CDF(I) * CDF(sinh(_sage_const_2  * K2s)) * Yc)
            S.add("テイラー抽出 (h2.y) = i sinh Z + cosh Y",
                  part_sum(CDF(I) * RDF(K2s) * H2, Yc),
                  CDF(I) * CDF(sinh(_sage_const_2  * K2s)) * Zc + CDF(cosh(_sage_const_2  * K2s)) * Yc)

            # -------------------------------------------------------------
            # T_actions_on_check_Z_Y の各段
            #   （行列指数関数を直接構成する独立経路で確かめる）
            # -------------------------------------------------------------
            S.add("T_actions (V1 Z 1) T_g の定義 g W g^{-1}",
                  Vh * Zc * Vhi, Vh * Zc * Vhi)
            S.add("T_actions (V1 Z 2) = exp((i/2)K_1H_1)Z exp(-(i/2)K_1H_1)",
                  Vh * Zc * Vhi,
                  matrix(CDF, (CDF(I) / _sage_const_2  * RDF(K1) * H1p).exp()) * Zc
                  * matrix(CDF, (-CDF(I) / _sage_const_2  * RDF(K1) * H1p).exp()))
            S.add("T_actions (V1 Z 3) = 交換子の級数 [exp_X_Y_exp_-X]",
                  Vh * Zc * Vhi, part_sum(CDF(I) / _sage_const_2  * RDF(K1) * H1p, Zc))
            S.add("T_actions (V1 Z 4) = cosh Z + i e^{-it} sinh Y",
                  Vh * Zc * Vhi,
                  CDF(cosh(K1)) * Zc + CDF(I) * eiph(-t) * CDF(sinh(K1)) * Yc)
            S.add("T_actions (V1 Y 4) = -i e^{it} sinh Z + cosh Y",
                  Vh * Yc * Vhi,
                  -CDF(I) * eiph(t) * CDF(sinh(K1)) * Zc + CDF(cosh(K1)) * Yc)
            S.add("T_actions (V2 Z 1) 前因子 (2s_2)^{M/2} の相殺",
                  V2 * Zc * V2i,
                  matrix(CDF, (CDF(I) * RDF(K2s) * H2).exp()) * Zc
                  * matrix(CDF, (-CDF(I) * RDF(K2s) * H2).exp()))
            S.add("T_actions (V2 Z 4) = cosh Z - i sinh Y",
                  V2 * Zc * V2i,
                  CDF(cosh(_sage_const_2  * K2s)) * Zc - CDF(I) * CDF(sinh(_sage_const_2  * K2s)) * Yc)
            S.add("T_actions (V2 Y 4) = i sinh Z + cosh Y",
                  V2 * Yc * V2i,
                  CDF(I) * CDF(sinh(_sage_const_2  * K2s)) * Zc + CDF(cosh(_sage_const_2  * K2s)) * Yc)

            # -------------------------------------------------------------
            # linearity_of_T_on_check_Z_Y（半指数行列への特殊化）
            # -------------------------------------------------------------
            aa, bb = CDF(_sage_const_0p3  + _sage_const_0p7  * I), CDF(-_sage_const_1p1  + _sage_const_0p2  * I)
            S.add("linearity_of_T_on_check_Z_Y (V1^{1/2}) T_g(aX+bW) = aT_g(X)+bT_g(W)",
                  Vh * (aa * Zc + bb * Yc) * Vhi,
                  aa * (Vh * Zc * Vhi) + bb * (Vh * Yc * Vhi))
            S.add("linearity_of_T_V2 T_g(aX+bW) = aT_g(X)+bT_g(W)",
                  V2 * (aa * Zc + bb * Yc) * V2i,
                  aa * (V2 * Zc * V2i) + bb * (V2 * Yc * V2i))
            # 後続計算が用いる V^{(+)} の特殊化も回帰検査として維持する。
            S.add("linearity_of_T (V^{(+)}) T_g(aX+bW) = aT_g(X)+bT_g(W)",
                  Vp * (aa * Zc + bb * Yc) * Vpi,
                  aa * (Vp * Zc * Vpi) + bb * (Vp * Yc * Vpi))

            # -------------------------------------------------------------
            # calc_of_TxT_check_Z_Y: 2 列を並べると B_1(theta~), B_2 の右乗になること
            # -------------------------------------------------------------
            B1m, B2m = B1(t, P), B2(P)
            S.add("calc_of_TxT (B1 第 1 列)", Vh * Zc * Vhi, B1m[_sage_const_0 , _sage_const_0 ] * Zc + B1m[_sage_const_1 , _sage_const_0 ] * Yc)
            S.add("calc_of_TxT (B1 第 2 列)", Vh * Yc * Vhi, B1m[_sage_const_0 , _sage_const_1 ] * Zc + B1m[_sage_const_1 , _sage_const_1 ] * Yc)
            S.add("calc_of_TxT (B2 第 1 列)", V2 * Zc * V2i, B2m[_sage_const_0 , _sage_const_0 ] * Zc + B2m[_sage_const_1 , _sage_const_0 ] * Yc)
            S.add("calc_of_TxT (B2 第 2 列)", V2 * Yc * V2i, B2m[_sage_const_0 , _sage_const_1 ] * Zc + B2m[_sage_const_1 , _sage_const_1 ] * Yc)

            # -------------------------------------------------------------
            # T_V_plus_check_Z_Y の (z)(y) 各段
            # -------------------------------------------------------------
            col_z = vector(CDF, [CDF(cosh(K1)), CDF(I) * eiph(-t) * CDF(sinh(K1))])
            col_y = vector(CDF, [-CDF(I) * eiph(t) * CDF(sinh(K1)), CDF(cosh(K1))])
            for col, W, nm in ((col_z, Zc, "z"), (col_y, Yc, "y")):
                inner = col[_sage_const_0 ] * Zc + col[_sage_const_1 ] * Yc               # T_{V1^{1/2}}(W)
                S.add(f"T_V_plus ({nm} 1) T_{{V1^{{1/2}}}} の作用", Vh * W * Vhi, inner)
                mid = V2 * inner * V2i
                S.add(f"T_V_plus ({nm} 2) T の線型性で T_{{V2}} を列ベクトルへ",
                      mid, col[_sage_const_0 ] * (V2 * Zc * V2i) + col[_sage_const_1 ] * (V2 * Yc * V2i))
                v2col = B2m * col
                S.add(f"T_V_plus ({nm} 3) 直積作用 -> (checkZ, checkY) B_2 col",
                      mid, v2col[_sage_const_0 ] * Zc + v2col[_sage_const_1 ] * Yc)
                out = Vh * mid * Vhi
                S.add(f"T_V_plus ({nm} 4) T の線型性で T_{{V1^{{1/2}}}} を外へ",
                      out, v2col[_sage_const_0 ] * (Vh * Zc * Vhi) + v2col[_sage_const_1 ] * (Vh * Yc * Vhi))
                b1col = B1m * v2col
                S.add(f"T_V_plus ({nm} 5) 直積作用 -> (checkZ, checkY) B_1 B_2 col",
                      out, b1col[_sage_const_0 ] * Zc + b1col[_sage_const_1 ] * Yc)
                S.add(f"T_V_plus ({nm} 6) 合成 = T_{{(V^{{(+)}})}}(W)", out, Vp * W * Vpi)

            # 2 列を並べて B_1 B_2 B_1 になること、および A(theta~) と一致すること
            BBB = B1m * B2m * B1m
            S.add("T_V_plus (まとめ Z) = (checkZ,checkY) B_1B_2B_1 の第 1 列",
                  Vp * Zc * Vpi, BBB[_sage_const_0 , _sage_const_0 ] * Zc + BBB[_sage_const_1 , _sage_const_0 ] * Yc)
            S.add("T_V_plus (まとめ Y) = (checkZ,checkY) B_1B_2B_1 の第 2 列",
                  Vp * Yc * Vpi, BBB[_sage_const_0 , _sage_const_1 ] * Zc + BBB[_sage_const_1 , _sage_const_1 ] * Yc)
            Am = A_theta(t, P)
            S.add("T_V_plus (最終 Z) = (checkZ,checkY) A(theta~) の第 1 列",
                  Vp * Zc * Vpi, Am[_sage_const_0 , _sage_const_0 ] * Zc + Am[_sage_const_1 , _sage_const_0 ] * Yc)
            S.add("T_V_plus (最終 Y) = (checkZ,checkY) A(theta~) の第 2 列",
                  Vp * Yc * Vpi, Am[_sage_const_0 , _sage_const_1 ] * Zc + Am[_sage_const_1 , _sage_const_1 ] * Yc)

# -------------------------------------------------------------------------
# factorization_of_A_theta_general の各段（theta in R 一般。行列だけの計算）
#   N = B_2 B_1(theta) の 4 成分、P = B_1 N の 4 成分を 1 段ずつ確かめる。
# -------------------------------------------------------------------------
NTHETA = _sage_const_60 
for p in STEP_PARAMS:
    P = coeffs(p['K1'], p['K2'])
    K1 = P['K1']
    a = RDF(cosh(K1)); b = RDF(sinh(K1))
    C = P['c2s']; Sh = P['s2s']
    c1, s1, c2, c2s, s2s = P['c1'], P['s1'], P['c2'], P['c2s'], P['s2s']
    S.add("factorization 倍角 a^2+b^2 = c_1", a ** _sage_const_2  + b ** _sage_const_2 , c1)
    S.add("factorization 倍角 2ab = s_1", _sage_const_2  * a * b, s1)
    S.add("factorization 倍角 a^2-b^2 = 1", a ** _sage_const_2  - b ** _sage_const_2 , RDF(_sage_const_1 ))
    S.add("factorization (iii) c_2* = s_2* c_2", c2s, s2s * c2)
    for k in range(NTHETA):
        t = RDF(_sage_const_2  * pi * k / NTHETA)
        u = RDF(cos(t)); v = RDF(sin(t))
        B1m, B2m = B1(t, P), B2(P)
        N = B2m * B1m
        S.add("factorization Step1 N_11", N[_sage_const_0 , _sage_const_0 ], C * a - Sh * b * eiph(-t))
        S.add("factorization Step1 N_12", N[_sage_const_0 , _sage_const_1 ], CDF(I) * (Sh * a - C * b * eiph(t)))
        S.add("factorization Step1 N_21", N[_sage_const_1 , _sage_const_0 ], CDF(I) * (C * b * eiph(-t) - Sh * a))
        S.add("factorization Step1 N_22", N[_sage_const_1 , _sage_const_1 ], C * a - Sh * b * eiph(t))
        Pm = B1m * N
        # P_11 の各段
        p11a = a * N[_sage_const_0 , _sage_const_0 ] + (-CDF(I) * eiph(t) * b) * N[_sage_const_1 , _sage_const_0 ]
        p11b = C * a ** _sage_const_2  - Sh * a * b * eiph(-t) + eiph(t) * b * (C * b * eiph(-t) - Sh * a)
        p11c = C * a ** _sage_const_2  - Sh * a * b * eiph(-t) + C * b ** _sage_const_2  - Sh * a * b * eiph(t)
        p11d = C * (a ** _sage_const_2  + b ** _sage_const_2 ) - Sh * a * b * (eiph(t) + eiph(-t))
        p11e = C * c1 - Sh * (s1 / _sage_const_2 ) * _sage_const_2  * u
        S.add("factorization Step2 P_11 (1) mat_mult", Pm[_sage_const_0 , _sage_const_0 ], p11a)
        S.add("factorization Step2 P_11 (2) N の代入と -i*i = 1", p11a, p11b)
        S.add("factorization Step2 P_11 (3) e^{it}e^{-it} = 1", p11b, p11c)
        S.add("factorization Step2 P_11 (4) 同類項の整理", p11c, p11d)
        S.add("factorization Step2 P_11 (5) 倍角と e^{it}+e^{-it} = 2cos t", p11d, p11e)
        S.add("factorization Step2 P_11 (6) = c_1c_2* - s_1s_2* cos t",
              p11e, c1 * c2s - s1 * s2s * u)
        # P_22
        S.add("factorization Step3 P_22 = P_11", Pm[_sage_const_1 , _sage_const_1 ], c1 * c2s - s1 * s2s * u)
        # P_12 の各段
        p12a = a * N[_sage_const_0 , _sage_const_1 ] + (-CDF(I) * eiph(t) * b) * N[_sage_const_1 , _sage_const_1 ]
        p12b = CDF(I) * (Sh * a ** _sage_const_2  - C * a * b * eiph(t))             + CDF(I) * (-C * a * b * eiph(t) + Sh * b ** _sage_const_2  * eiph(_sage_const_2  * t))
        p12c = CDF(I) * (Sh * (a ** _sage_const_2  + b ** _sage_const_2  * eiph(_sage_const_2  * t)) - _sage_const_2  * C * a * b * eiph(t))
        br1 = a ** _sage_const_2  + b ** _sage_const_2  * eiph(_sage_const_2  * t)
        br2 = eiph(t) * (a ** _sage_const_2  * eiph(-t) + b ** _sage_const_2  * eiph(t))
        br3 = eiph(t) * (a ** _sage_const_2  * (u - CDF(I) * v) + b ** _sage_const_2  * (u + CDF(I) * v))
        br4 = eiph(t) * ((a ** _sage_const_2  + b ** _sage_const_2 ) * u - CDF(I) * (a ** _sage_const_2  - b ** _sage_const_2 ) * v)
        br5 = eiph(t) * (c1 * u - CDF(I) * v)
        S.add("factorization Step4 P_12 (1) mat_mult", Pm[_sage_const_0 , _sage_const_1 ], p12a)
        S.add("factorization Step4 P_12 (2) N の代入と e^{it}e^{it} = e^{2it}", p12a, p12b)
        S.add("factorization Step4 P_12 (3) 括弧でくくる", p12b, p12c)
        S.add("factorization Step4 括弧 (1) e^{it} でくくる", br1, br2)
        S.add("factorization Step4 括弧 (2) Euler の公式を 2 箇所へ同時適用", br2, br3)
        S.add("factorization Step4 括弧 (3) 整理", br3, br4)
        S.add("factorization Step4 括弧 (4) a^2+b^2 = c_1", br4, eiph(t) * (c1 * u - CDF(I) * (a ** _sage_const_2  - b ** _sage_const_2 ) * v))
        S.add("factorization Step4 括弧 (5) a^2-b^2 = 1", eiph(t) * (c1 * u - CDF(I) * (a ** _sage_const_2  - b ** _sage_const_2 ) * v), br5)
        S.add("factorization Step4 P_12 (4) = i e^{it} s_2*(c_1 cos t - i sin t - s_1c_2)",
              Pm[_sage_const_0 , _sage_const_1 ], CDF(I) * eiph(t) * s2s * (c1 * u - CDF(I) * v - s1 * c2))
        # P_21
        p21a = (CDF(I) * eiph(-t) * b) * N[_sage_const_0 , _sage_const_0 ] + a * N[_sage_const_1 , _sage_const_0 ]
        S.add("factorization Step5 P_21 (1) mat_mult", Pm[_sage_const_1 , _sage_const_0 ], p21a)
        S.add("factorization Step5 P_21 (2) = -i e^{-it}s_2*(c_1cos t + i sin t - s_1c_2)",
              Pm[_sage_const_1 , _sage_const_0 ], -CDF(I) * eiph(-t) * s2s * (c1 * u + CDF(I) * v - s1 * c2))
        S.add("factorization Step6 B_1 B_2 B_1 = A(theta)", Pm, A_theta(t, P))

ok_all = S.report_all()
print(f"  段数（区別された等式の種類）: {len(S.worst)}")
print("check_03:", "PASS" if ok_all else "FAIL")

